/** Set by vite.config.ts at build time. */
declare const __APP_VERSION__: string;
/** The commit the app was built from, or "" when unknown. */
declare const __APP_COMMIT__: string;
/** The commit's first 7 characters, with "-dirty" for uncommitted changes, or "unknown". */
declare const __APP_REVISION__: string;
/** Built with `GWAR_CAPTURE_CHECK=1`: the bundle includes the screen-capture check page. */
declare const __CAPTURE_CHECK__: boolean;
